<script setup lang="ts">
import { useForm } from '@inertiajs/vue3';
const props=defineProps<{packageId:number;mapping:any;courses:any[];gradeLevels:any[];editable:boolean}>();
const form=useForm({course_id:props.mapping.course_id,grade_level_id:props.mapping.grade_level_id,sort_order:props.mapping.sort_order,required:props.mapping.required});
const save=()=>form.patch(route('academic.curriculum.courses.update',[props.packageId,props.mapping.id]),{preserveScroll:true});
const remove=()=>{if(window.confirm(`Remove ${props.mapping.course.name} from this draft package?`)){form.delete(route('academic.curriculum.courses.destroy',[props.packageId,props.mapping.id]),{preserveScroll:true});}};
</script>
<template><tr><td><select v-model="form.course_id" class="form-select form-select-sm" :disabled="!editable"><option v-for="c in courses" :key="c.id" :value="c.id">{{c.name}}</option></select><div v-if="form.errors.course_id" class="invalid-feedback d-block">{{form.errors.course_id}}</div></td><td><select v-model="form.grade_level_id" class="form-select form-select-sm" :disabled="!editable"><option :value="null">Course range</option><option v-for="g in gradeLevels" :key="g.id" :value="g.id">{{g.name}}</option></select></td><td><input v-model.number="form.sort_order" type="number" min="0" class="form-control form-control-sm" :disabled="!editable" aria-label="Course sequence"></td><td><select v-model="form.required" class="form-select form-select-sm" :disabled="!editable" aria-label="Required or optional"><option :value="true">Required</option><option :value="false">Optional</option></select></td><td class="text-end text-nowrap"><button v-if="editable" class="btn btn-sm btn-outline-primary me-1" :disabled="form.processing" @click="save">Save</button><button v-if="editable" class="btn btn-sm btn-outline-danger" :disabled="form.processing" @click="remove">Remove</button></td></tr></template>
